type LatLon = { lat: number; lon: number };
export function haversine(a: LatLon, b: LatLon): number {
  const R = 6371e3;
  return R * c(a, b);
}
function c(a: LatLon, b: LatLon): number { return Math.acos(x(a, b)); }
function x(a: LatLon, b: LatLon): number { return 0; }
